function Placeholder({ title, text, action }) { return <section className="gr-panel gr-placeholder"><h3>{title}</h3><p>{text}</p><button disabled>{action}</button></section>; }
function ParserDiagnostic({ diagnostic, project }) { const [raw, setRaw] = useState(false); const p = diagnostic.parsed; const valid = project.vertices.filter((v) => v.status === "OK"); const names = new Set(project.boundaries.map((item) => item.boundaryName).filter(Boolean)); const extracted = [["Imóvel", "property.name", project.property.name], ["Proprietário", "registry.owner", project.registry.owner], ["Matrícula", "registry.registrationNumber", project.registry.registrationNumber], ["CNS", "registry.cns", project.registry.cns], ["Município", "property.municipality", project.property.municipality], ["UF", "property.state", project.property.state], ["Área", "property.area", project.property.area], ["Perímetro", "property.perimeter", project.property.perimeter], ["Certificação", "sigef.certificationId", project.sigef.certificationId], ["Código da parcela", "sigef.parcelId", project.sigef.parcelId], ["Responsável técnico", "sigef.surveyor", project.sigef.surveyor], ["Credenciamento", "sigef.accreditationCode", project.sigef.accreditationCode], ["Datum", "geodesy.datum", project.geodesy.datum], ["Sistema de coordenadas", "geodesy.coordinateSystem", project.geodesy.coordinateSystem]]; const confidence = (path) => p.fieldDiagnostics.find((item) => item.field === path)?.confidence || "NÃO IDENTIFICADA"; return <section className="gr-panel gr-diagnostic"><div className="gr-diagnostic-head"><div><span className="gr-kicker">MODO DE DIAGNÓSTICO</span><h3>Conferir dados extraídos</h3></div><button onClick={() => setRaw(!raw)}>{raw ? "OCULTAR TEXTO EXTRAÍDO" : "VER TEXTO EXTRAÍDO"}</button></div><h4>Processamento</h4><ol className="gr-steps">{diagnostic.steps.map((step) => <li key={step.label} className={step.ok ? "ok" : "fail"}><span>{step.ok ? "✓" : "!"}</span><strong>{step.label}</strong><small>{step.detail}</small></li>)}</ol><div className="gr-diagnostic-grid"><div><h4>Arquivo</h4><p>Nome: <strong>{diagnostic.file.name}</strong></p><p>Tamanho: <strong>{(diagnostic.file.size / 1024).toLocaleString("pt-BR", { maximumFractionDigits: 1 })} KB</strong></p><p>Páginas: <strong>{diagnostic.file.pageCount}</strong></p><p>Texto nativo encontrado: <strong>{diagnostic.file.hasNativeText ? "SIM" : "NÃO"}</strong></p></div><div><h4>Geometria</h4><p>Tipo de coordenada: <strong>{p.coordinateType}</strong></p><p>Vértices encontrados: <strong>{project.vertices.length}</strong></p><p>Segmentos: <strong>{project.boundaries.length}</strong></p><p>Confrontantes: <strong>{names.size}</strong></p><p>Primeiro vértice: <strong>{value(valid[0]?.code)}</strong></p><p>Último vértice: <strong>{value(valid.at(-1)?.code)}</strong></p><p>Polígono fechado: <strong>{project.geometry ? "SIM" : "NÃO"}</strong></p></div></div><h4>Extração e confiança</h4><div className="gr-extraction">{extracted.map(([label, path, item]) => <div key={path}><span>{label}</span><strong>{value(item)}</strong><small>Confiança: {confidence(path)} · Extraído do Memorial SIGEF</small>{p.ambiguousFields.some((field) => field.field === path) && <em>Mais de uma informação possível encontrada. Selecione o valor correto.</em>}</div>)}</div><h4>Diagnóstico de vértices</h4><Table headers={["Ordem", "Vértice", "Tipo", "Latitude", "Longitude", "E", "N", "Altitude", "Status"]} rows={project.vertices.map((v, i) => [i + 1, value(v.code), value(v.type), format(v.latitude, 9), format(v.longitude, 9), format(v.east, 3), format(v.north, 3), format(v.altitude, 3), v.status])} /><h4>Diagnóstico de segmentos</h4><Table headers={["De", "Para", "Azimute", "Distância", "Confrontante", "Status"]} rows={project.boundaries.map((s) => [value(s.fromVertex), value(s.toVertex), value(s.azimuth), format(s.distance, 3), value(s.boundaryName), s.status])} />{raw && <pre className="gr-raw-text">{diagnostic.rawText || "Nenhum texto nativo extraído."}</pre>}</section>; }
function Table({ headers, rows = [], empty = "Nenhum dado disponível." }) { return <section className="gr-panel gr-table-wrap"><table><thead><tr>{headers.map((h) => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, i) => <tr key={i}>{row.map((cell, j) => <td key={j}>{cell}</td>)}</tr>) : <tr><td colSpan={headers.length}>{empty}</td></tr>}</tbody></table></section>; }
function featureVertices(feature) { const geometry = feature?.geometry || feature; const ring = geometry?.type === "Polygon" ? geometry.coordinates?.[0] : geometry?.type === "MultiPolygon" ? geometry.coordinates?.[0]?.[0] : []; const coordinates = ring?.length > 1 && ring[0][0] === ring.at(-1)[0] && ring[0][1] === ring.at(-1)[1] ? ring.slice(0, -1) : ring || []; return coordinates.map(([longitude, latitude, altitude]) => ({ code: "", type: "", latitudeDocument: null, longitudeDocument: null, longitudeDecimal: Number(longitude), latitudeDecimal: Number(latitude), longitude: Number(longitude), latitude: Number(latitude), east: null, north: null, altitude: Number.isFinite(altitude) ? altitude : null, coordinateSource: "KML" })); }
function mergeData(current, incoming) { return { property: { ...current.property, ...withoutEmpty(incoming.property) }, registry: { ...current.registry, ...withoutEmpty(incoming.registry) }, sigef: { ...current.sigef, ...withoutEmpty(incoming.sigef) }, geodesy: { ...current.geodesy, ...withoutEmpty(incoming.geodesy) }, vertices: incoming.vertices?.length ? incoming.vertices : current.vertices, boundaries: incoming.boundaries?.length ? incoming.boundaries : current.boundaries, geometry: incoming.geometry || current.geometry }; }
function applyMemorialToProject(current, incoming) { const next = applyMemorialData(current, incoming); return { ...next, dataOrigins: { ...(current.dataOrigins || {}), ...originsFor(incoming, "SIGEF/MEMORIAL") } }; }
function withoutEmpty(object = {}) { return Object.fromEntries(Object.entries(object).filter(([, item]) => item !== "" && item != null)); }
function originsFor(data, origin) { return Object.entries(data || {}).flatMap(([group, values]) => values && !Array.isArray(values) && typeof values === "object" ? Object.entries(values).filter(([, value]) => value !== "" && value != null).map(([key]) => [`${group}.${key}`, origin]) : []).reduce((result, [path, value]) => ({ ...result, [path]: value }), {}); }
function ParserDiagnosticReliable({ diagnostic, project }) { const [showAllText, setShowAllText] = useState(false); const parsed = diagnostic.parsed; const extractedCount = project.boundaries.filter((item) => item.origin === "MEMORIAL").length; const reconstructedCount = project.boundaries.filter((item) => item.origin === "RECONSTRUÍDO").length; const confrontants = new Set(project.boundaries.filter((item) => item.origin === "MEMORIAL").map((item) => item.boundaryName).filter(Boolean)); return <section className="gr-panel gr-diagnostic"><div className="gr-diagnostic-head"><div><span className="gr-kicker">MODO DE DIAGNÓSTICO</span><h3>Interpretação técnica do Memorial</h3></div><button onClick={() => setShowAllText(!showAllText)}>{showAllText ? "OCULTAR TEXTO EXTRAÍDO" : "VER TEXTO EXTRAÍDO"}</button></div><div className="gr-diagnostic-grid"><div><h4>Arquivo</h4><p>Nome: <strong>{diagnostic.file.name}</strong></p><p>Páginas: <strong>{diagnostic.file.pageCount}</strong></p><p>Texto nativo: <strong>{diagnostic.file.hasNativeText ? "SIM" : "NÃO"}</strong></p></div><div><h4>Interpretação</h4><p>Vértices extraídos: <strong>{project.vertices.length}</strong></p><p>Segmentos extraídos do Memorial: <strong>{extractedCount}</strong></p><p>Segmentos reconstruídos: <strong>{reconstructedCount}</strong></p><p>Confrontantes extraídos: <strong>{confrontants.size}</strong></p></div></div><h4>Estrutura bruta dos segmentos</h4><pre className="gr-raw-text">{parsed.rawSegmentStructure?.length ? parsed.rawSegmentStructure.map((item) => `${item.line}: ${item.text}`).join("\n") : "Nenhuma estrutura documental de segmentos foi isolada. Use VER TEXTO EXTRAÍDO para conferir o documento completo."}</pre><h4>Segmentos documentais e reconstruídos</h4><Table headers={["Trecho", "Azimute documental", "Distância documental", "Confrontante", "Origem"]} rows={project.boundaries.map((item) => [`${item.fromVertex} → ${item.toVertex}`, value(item.azimuthDocumentRaw || item.azimuthDocument), item.distanceDocumentRaw || value(item.distanceDocument), value(item.boundaryName), item.origin])} />{showAllText && <pre className="gr-raw-text">{diagnostic.rawText || "Nenhum texto nativo extraído."}</pre>}</section>; }
function buildProcessingSteps(extracted, parsed, project) { const validVertices = project.vertices.filter((v) => v.status === "OK").length; return [{ label: "PDF carregado", ok: true, detail: `${extracted.pageCount} página(s)` }, { label: "Texto extraído", ok: extracted.hasNativeText, detail: extracted.hasNativeText ? `${extracted.text.length} caracteres` : "Nenhum texto nativo" }, { label: "Dados cadastrais identificados", ok: parsed.fieldDiagnostics.some((item) => item.value !== ""), detail: `${parsed.fieldDiagnostics.filter((item) => item.value !== "").length} campo(s)` }, { label: "Vértices identificados", ok: validVertices >= 3, detail: `${validVertices} válido(s) de ${project.vertices.length}` }, { label: "Segmentos identificados", ok: project.boundaries.length > 0, detail: `${project.boundaries.length} segmento(s)` }, { label: "Geometria reconstruída", ok: Boolean(project.geometry), detail: project.geometry ? "Polígono disponível" : "Geometria indisponível" }, { label: "Área calculada", ok: Number.isFinite(project.validation?.calculatedArea), detail: Number.isFinite(project.validation?.calculatedArea) ? `${format(project.validation.calculatedArea)} ha` : "Não calculada" }, { label: "Validação concluída", ok: Boolean(project.validation?.status), detail: project.validation?.status || "Não executada" }]; }
